// Package db is the typed query layer over SQLite.
//
// Originally generated by sqlc from internal/db/queries/*.sql. That tool was
// dropped after it silently corrupted the embedded SQL text of queries added
// in Phase 3 (reproducible: a SELECT with a trailing ORDER BY had its final
// keyword overwritten, with sqlc reporting success) and crashed outright on
// an older version — a correctness risk not worth the convenience at this
// project's scale. This package's original three files (users, sessions,
// activation — Phase 1) were verified working before the bug was found and
// are kept as-is; everything since is hand-written directly in this package,
// following the same shape (a *Params struct per multi-argument query, one
// method per query on *Queries) so nothing upstream had to change.
package db

import (
	"context"
	"database/sql"
)

type DBTX interface {
	ExecContext(context.Context, string, ...interface{}) (sql.Result, error)
	PrepareContext(context.Context, string) (*sql.Stmt, error)
	QueryContext(context.Context, string, ...interface{}) (*sql.Rows, error)
	QueryRowContext(context.Context, string, ...interface{}) *sql.Row
}

func New(db DBTX) *Queries {
	return &Queries{db: db}
}

type Queries struct {
	db DBTX
}

func (q *Queries) WithTx(tx *sql.Tx) *Queries {
	return &Queries{
		db: tx,
	}
}
